-- One row per file a run published under the data root (feeds and the run manifest). A row is inserted only
-- after the file and its directories were fsynced in place, so the ledger never names a file that isn't durable;
-- resume compares regenerated bytes against it and never overwrites a published file.
CREATE TABLE {meta}.published_files (
    run_id           text NOT NULL REFERENCES {meta}.generation_runs (run_id),
    rel_path         text NOT NULL CHECK (rel_path !~ '(^/|\.\.)'),
    feed             text NOT NULL,
    format           text NOT NULL CHECK (format IN ('csv', 'jsonl', 'json')),
    schema_version   integer NOT NULL CHECK (schema_version >= 1),
    records          bigint NOT NULL CHECK (records >= 0),
    bytes            bigint NOT NULL CHECK (bytes >= 0),
    sha256           char(64) NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    start_event_time timestamptz,
    end_event_time   timestamptz CHECK (end_event_time >= start_event_time),
    published_at     timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (run_id, rel_path)
);
